package com.example.starter.common;

/**
 * 业务拒绝原因码，客户端可据此区分失败类型。
 */
public enum ErrorReason {
    /** 请求时隙超出预测可见窗口。 */
    WINDOW_GAP,
    /** 预测最低仰角低于站点门槛。 */
    ELEVATION_BELOW_THRESHOLD,
    /** 时隙时长乘以站点容量容纳不下计划数据量。 */
    CAPACITY_EXCEEDED,
    /** 同站天线在该时段已被其他已确认时隙占用。 */
    ANTENNA_OVERLAP,
    /** 请求基于的预测版本已被修订，不能凭过期预测锁定天线。 */
    STALE_PREDICTION,
    /** 同一幂等键携带了不同参数。 */
    REQUEST_ID_CONFLICT,
    /** 当前状态不允许该操作（如重复完成、取消已完成记录）。 */
    INVALID_STATE,
    /** 完成回报的实际字节数超过计划数据量。 */
    ACTUAL_EXCEEDS_PLANNED,
    /** 引用的资源不存在。 */
    NOT_FOUND
}
'@
[System.IO.File]::WriteAllText("$base\common\ErrorReason.java", $reason, $enc)
$ex = @'
package com.example.starter.common;

import org.springframework.http.HttpStatus;

/**
 * 业务异常：携带 HTTP 状态与可区分的拒绝原因码。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;
    private final ErrorReason reason;

    public ApiException(HttpStatus status, ErrorReason reason, String message) {
        super(message);
        this.status = status;
        this.reason = reason;
    }

    public HttpStatus status() {
        return status;
    }

    public ErrorReason reason() {
        return reason;
    }

    /**
     * 构造 409 冲突异常。
     */
    public static ApiException conflict(ErrorReason reason, String message) {
        return new ApiException(HttpStatus.CONFLICT, reason, message);
    }

    /**
     * 构造 404 异常。
     */
    public static ApiException notFound(String message) {
        return new ApiException(HttpStatus.NOT_FOUND, ErrorReason.NOT_FOUND, message);
    }

    /**
     * 构造 422 异常。
     */
    public static ApiException unprocessable(ErrorReason reason, String message) {
        return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, reason, message);
    }
}
'@
[System.IO.File]::WriteAllText("$base\common\ApiException.java", $ex, $enc)"}

