        long tooManyBytes = AllocationService.BYTES_PER_MB + 1;
        assertThatThrownBy(() -> allocationService.complete(allocation.id(),
                new CompletionRequest("c-over", tooManyBytes)))
                .isInstanceOfSatisfying(ApiException.class,
